<?php
/** Inline intake review using the existing immutable item-review endpoint. */
function receipt_review_view(PDO $pdo,array $receipt,array $suggestions): void
{
    $rid=(int)$receipt['ReceiptID'];$current=item_review_current($pdo,$rid,'intake');$data=$current?$current['data']:['merchant'=>$suggestions['merchant']??'','reference'=>$suggestions['reference']??'','date'=>$suggestions['transaction_date']??'','currency'=>($suggestions['currency']??'')==='PHP'?'PHP':'','declared_total'=>$suggestions['total_amount']??'','items'=>$suggestions['items']??[],'complete'=>false,'incomplete_reason'=>$suggestions['itemization_note']??''];$e='ui_escape';
    $model=['receipt_id'=>$rid,'draft_id'=>null,'revision'=>(int)($current['revision_number']??0),'data'=>$data,'csrf_token'=>csrf_token()];
    ?><p id="ir-status" role="status"><?= $current?'Receipt details saved. Changes require a new confirmation.':'Check the original receipt, then save its details.' ?></p><form id="ir-form" class="ocr-review-form">
    <?php foreach(['merchant'=>'Merchant','reference'=>'Reference','date'=>'Date','declared_total'=>'Total (PHP)'] as $key=>$label): ?><label><?= $e($label) ?><input id="ir-<?= $e($key) ?>" type="<?= $key==='date'?'date':'text' ?>" value="<?= $e($data[$key]) ?>"<?= $key==='declared_total'?' inputmode="decimal" required':'' ?> maxlength="<?= $key==='merchant'?255:($key==='reference'?100:32) ?>"></label><?php endforeach; ?>
    <label>Currency<select id="ir-currency" required><option value="">Confirm currency</option><option value="PHP"<?= $data['currency']==='PHP'?' selected':'' ?>>PHP</option></select></label>
    <details<?= $data['items']?' open':'' ?>><summary>Receipt Items<?= $data['items']?' · '.count($data['items']):' (Optional)' ?></summary><div class="ocr-items-wrap"><table><thead><tr><th>Item</th><th>Qty</th><th>Line Total</th><th>Action</th></tr></thead><tbody id="ir-items"></tbody></table></div><button id="ir-add" type="button" class="ui-button">+ Add Item</button><p id="ir-total" role="status"></p><label class="ocr-check"><input id="ir-complete" type="checkbox"<?= $data['complete']?' checked':'' ?>>All items are included and match the receipt total</label></details>
    <label>Missing items or differences<textarea id="ir-reason" maxlength="1000" placeholder="If you did not enter all items, explain what is missing or why you are checking only the receipt total."><?= $e($data['incomplete_reason']) ?></textarea></label><label class="ocr-check"><input id="ir-confirm" type="checkbox" required>I checked these details against the receipt</label><div class="ocr-actions"><button id="ir-save" type="submit" class="ocr-primary">Save Receipt Details</button><button id="ir-retry" type="button" class="ui-button" hidden>Check Original Save Result</button></div><p class="ocr-help">Saving receipt details does not record a financial transaction.</p><noscript><p>Enable JavaScript to confirm receipt details. Uploading the image alone does not record money.</p></noscript></form>
    <a id="ocr-continue" class="ocr-primary" href="general_journal.php?receipt_id=<?= $rid ?>"<?= !$current?' aria-disabled="true" tabindex="-1"':'' ?>>Continue to General Journal</a><script id="ir-data" type="application/json"><?= json_encode($model,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR) ?></script><?php
}
